using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;

namespace Sace.Api.Services;

public interface IDocumentLineItemMatcher {
  IReadOnlyList<DocumentLineItemMatch> Match(IReadOnlyList<DocumentLineItem> left,IReadOnlyList<DocumentLineItem> right);
}

public sealed class DocumentLineItemMatcher : IDocumentLineItemMatcher {
  public IReadOnlyList<DocumentLineItemMatch> Match(IReadOnlyList<DocumentLineItem> left,IReadOnlyList<DocumentLineItem> right){
    var result=new List<DocumentLineItemMatch>();var used=new HashSet<Guid>();
    foreach(var item in left.OrderBy(x=>x.Sequence)){
      var (method,key,candidates)=Candidates(item,right.Where(x=>!used.Contains(x.Id)).ToList());
      if(candidates.Count==1){var target=candidates[0];used.Add(target.Id);result.Add(M(item,target,method,key,LineItemMatchStatus.MATCHED,$"Partidas vinculadas mediante {method}: {key}."));}
      else if(candidates.Count>1)result.Add(M(item,null,method,key,LineItemMatchStatus.AMBIGUOUS,"Se encontraron múltiples partidas candidatas."));
      else result.Add(M(item,null,LineItemMatchMethod.NONE,null,LineItemMatchStatus.UNMATCHED_LEFT,"La partida izquierda no tiene candidata determinista."));
    }
    foreach(var item in right.Where(x=>!used.Contains(x.Id)).OrderBy(x=>x.Sequence))result.Add(M(null,item,LineItemMatchMethod.NONE,null,LineItemMatchStatus.UNMATCHED_RIGHT,"La partida derecha no tiene candidata determinista."));
    return result;
  }
  private static (LineItemMatchMethod method,string? key,List<DocumentLineItem> candidates) Candidates(DocumentLineItem item,List<DocumentLineItem> available){
    var part=Key(item.PartNumber??item.Sku);if(part is not null){var rows=available.Where(x=>Key(x.PartNumber??x.Sku)==part).ToList();return(LineItemMatchMethod.PART_NUMBER,part,rows);}
    var number=Key(item.ItemNumber);if(number is not null){var rows=available.Where(x=>Key(x.ItemNumber)==number).ToList();if(rows.Count>0)return(LineItemMatchMethod.ITEM_REFERENCE,number,rows);}
    var strong=Strong(item);if(strong is not null)return(LineItemMatchMethod.DESCRIPTION_QUANTITY_UNIT,strong,available.Where(x=>Strong(x)==strong).ToList());
    return(LineItemMatchMethod.NONE,null,[]);
  }
  private static string? Strong(DocumentLineItem item){var description=Text(item.Description);var unit=Unit(item.Unit);return description is null||!item.Quantity.HasValue||unit is null?null:$"{description}|{item.Quantity.Value.ToString(CultureInfo.InvariantCulture)}|{unit}";}
  private static string? Key(string? value)=>string.IsNullOrWhiteSpace(value)?null:Regex.Replace(value.Trim().ToUpperInvariant(),@"[^A-Z0-9]","");
  private static string? Text(string? value)=>string.IsNullOrWhiteSpace(value)?null:Regex.Replace(value.Trim().ToUpperInvariant(),@"[\p{P}\s]+"," ").Trim();
  private static string? Unit(string? value)=>value?.Trim().ToUpperInvariant() switch{"PIEZA" or "PIEZAS" or "PZ" or "PZS" or "PCS"=>"PZA","KGS"=>"KG","LBS"=>"LB",var v=>v};
  private static DocumentLineItemMatch M(DocumentLineItem? left,DocumentLineItem? right,LineItemMatchMethod method,string? key,LineItemMatchStatus status,string explanation)=>new(){LeftLineItemId=left?.Id,RightLineItemId=right?.Id,MatchMethod=method,MatchKey=key,Status=status,Explanation=explanation,LeftItemSnapshot=left is null?null:JsonSerializer.Serialize(Snapshot(left)),RightItemSnapshot=right is null?null:JsonSerializer.Serialize(Snapshot(right))};
  private static object Snapshot(DocumentLineItem x)=>new{x.Sequence,x.ItemNumber,x.PartNumber,x.Sku,x.Description,x.Quantity,x.Unit,x.UnitValue,x.TotalValue,x.Currency,x.TariffFraction,x.Nico,x.GrossWeight,x.NetWeight,x.CountryOfOrigin,x.RawLocator,x.ExtractionMethod,x.Confidence};
}

public interface IDocumentReconciliationService {
  Task<IReadOnlyList<DocumentReconciliationResult>> RunAsync(Guid operationId,Guid userId,CancellationToken ct=default);
}

public sealed class DocumentReconciliationService : IDocumentReconciliationService {
  private readonly SaceDbContext db;private readonly IDocumentLineItemMatcher matcher;private readonly IInvoiceCovePairingService invoiceCovePairing;private readonly IInvoiceCoveLineMatcher invoiceCoveLineMatcher;
  public DocumentReconciliationService(SaceDbContext db,IDocumentLineItemMatcher matcher):this(db,matcher,new InvoiceCovePairingService(),new InvoiceCoveLineMatcher()){}
  public DocumentReconciliationService(SaceDbContext db,IDocumentLineItemMatcher matcher,IInvoiceCovePairingService invoiceCovePairing,IInvoiceCoveLineMatcher invoiceCoveLineMatcher){this.db=db;this.matcher=matcher;this.invoiceCovePairing=invoiceCovePairing;this.invoiceCoveLineMatcher=invoiceCoveLineMatcher;}
  private sealed record Pair(OperationDocument? Left,OperationDocument? Right,bool Ambiguous,string Explanation,InvoiceCovePairingStatus? PairingStatus=null,InvoiceCovePairingMethod? PairingMethod=null,string? PairingReasonCode=null);
  private sealed record ValueSnapshot(Guid? FieldId,string? Raw,string? Normalized,ExtractionMethod? Method,string? Location=null);
  private static readonly Dictionary<string,string[]> Aliases=new(StringComparer.OrdinalIgnoreCase){["COMMERCIAL_INVOICE"]=["COMMERCIAL_INVOICE","INVOICE"],["COVE_ACK"]=["COVE_ACK"],["PACKING_LIST"]=["PACKING_LIST"],["TRANSPORT_DOCUMENT"]=["TRANSPORT_DOCUMENT"],["PEDIMENTO"]=["PEDIMENTO"]};

  public async Task<IReadOnlyList<DocumentReconciliationResult>> RunAsync(Guid operationId,Guid userId,CancellationToken ct=default){
    var operation=await db.TradeOperations.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==operationId,ct)??throw new KeyNotFoundException("Operación no localizada.");var validUser=await ValidUser(userId,ct);
    db.SystemAuditLogs.Add(new SystemAuditLog{UserId=validUser,Action="DOCUMENT_RECONCILIATION_STARTED",EntityType="TradeOperation",EntityId=operationId.ToString(),Details="Inició la reconciliación documental integral."});await db.SaveChangesAsync(ct);
    var documents=await db.OperationDocuments.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.DocumentType).Include(x=>x.References).Include(x=>x.Fields).Include(x=>x.LineItems).Include(x=>x.Participants).Include(x=>x.IntelligenceAnalyses).ToListAsync(ct);
    var profiles=await db.DocumentReconciliationProfiles.AsNoTracking().Where(x=>x.Status==ReconciliationProfileStatus.ACTIVE&&(x.EffectiveFrom==null||x.EffectiveFrom<=operation.OperationDate)&&(x.EffectiveTo==null||operation.OperationDate<=x.EffectiveTo)).Include(x=>x.Fields.Where(f=>f.IsActive)).ThenInclude(x=>x.CrossValidationRule).OrderBy(x=>x.Code).ToListAsync(ct);
    var crosses=await db.CrossValidationResults.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.SourceField).Include(x=>x.TargetField).OrderByDescending(x=>x.EvaluatedAt).ToListAsync(ct);var results=new List<DocumentReconciliationResult>();
    var relationships=await db.DocumentRelationshipCandidates.AsNoTracking().Where(x=>documents.Select(d=>d.Id).Contains(x.SourceDocumentId)&&documents.Select(d=>d.Id).Contains(x.TargetDocumentId)).ToListAsync(ct);
    foreach(var profile in profiles){var left=OfType(documents,profile.LeftDocumentTypeCode);var right=OfType(documents,profile.RightDocumentTypeCode);if(left.Count==0&&right.Count==0)continue;var pairs=profile.Code=="RECON-INV-COVE-V2"?invoiceCovePairing.Pair(left,right,relationships).Select(x=>new Pair(x.Invoice,x.Cove,x.Status==InvoiceCovePairingStatus.MANUAL_REVIEW,x.Explanation,x.Status,x.Method,x.ReasonCode)).ToList():PairDocuments(left,right);foreach(var pair in pairs){var result=profile.Code=="RECON-INV-COVE-V2"?BuildInvoiceCoveV2(operation,profile,pair):Build(operation,profile,pair,crosses);db.DocumentReconciliationResults.Add(result);results.Add(result);}}
    var manual=results.Count(x=>x.Outcome==ReconciliationOutcome.MANUAL_REVIEW);db.SystemAuditLogs.Add(new SystemAuditLog{UserId=validUser,Action="DOCUMENT_RECONCILIATION_COMPLETED",EntityType="TradeOperation",EntityId=operationId.ToString(),Details=$"{results.Count} reconciliaciones: {results.Count(x=>x.Outcome==ReconciliationOutcome.MATCH)} coincidencias, {results.Count(x=>x.Outcome==ReconciliationOutcome.WITH_DIFFERENCES)} con diferencias, {manual} en revisión manual."});if(manual>0)db.SystemAuditLogs.Add(new SystemAuditLog{UserId=validUser,Action="DOCUMENT_RECONCILIATION_MANUAL_REVIEW",EntityType="TradeOperation",EntityId=operationId.ToString(),Details=$"{manual} reconciliaciones requieren revisión humana."});await db.SaveChangesAsync(ct);return results;
  }

  private DocumentReconciliationResult BuildInvoiceCoveV2(TradeOperation operation,DocumentReconciliationProfile profile,Pair pair){
    var result=new DocumentReconciliationResult{TradeOperationId=operation.Id,ProfileId=profile.Id,ProfileCode=profile.Code,ProfileVersion=profile.Version,LeftDocumentId=pair.Left?.Id,RightDocumentId=pair.Right?.Id,PairingStatus=pair.PairingStatus,PairingMethod=pair.PairingMethod,PairingReasonCode=pair.PairingReasonCode,PairingExplanation=pair.Explanation,EvaluatedAt=DateTime.UtcNow};
    foreach(var field in profile.Fields.Where(x=>x.LineItemScope==LineItemScope.HEADER).OrderBy(x=>x.Sequence))result.FieldResults.Add(CompareV2(field,HeaderValue(pair.Left,field.LeftFieldCode),HeaderValue(pair.Right,field.RightFieldCode),pair.Left,pair.Right,null,null));
    var leftItems=pair.Left?.LineItems.ToList()??[];var rightItems=pair.Right?.LineItems.ToList()??[];result.LineItemsLeft=leftItems.Count;result.LineItemsRight=rightItems.Count;
    if(pair.Left is not null&&pair.Right is not null){foreach(var match in invoiceCoveLineMatcher.Match(leftItems,rightItems)){result.LineItemMatches.Add(match);if(match.Status==LineItemMatchStatus.MATCHED){var left=leftItems.Single(x=>x.Id==match.LeftLineItemId);var right=rightItems.Single(x=>x.Id==match.RightLineItemId);var rows=new List<DocumentReconciliationFieldResult>();foreach(var field in profile.Fields.Where(x=>x.LineItemScope==LineItemScope.LINE_ITEM).OrderBy(x=>x.Sequence))rows.Add(CompareV2(field,LineValueV2(left,field.LeftFieldCode),LineValueV2(right,field.RightFieldCode),pair.Left,pair.Right,left.Id,right.Id));ApplyJointLineSemantics(rows);result.FieldResults.AddRange(rows);}else AddUnmatchedLineResult(result,profile,match,leftItems,rightItems,pair.Left,pair.Right);}}
    result.LineItemsMatched=result.LineItemMatches.Count(x=>x.Status==LineItemMatchStatus.MATCHED);result.LineItemsUnmatched=result.LineItemMatches.Count(x=>x.Status is LineItemMatchStatus.UNMATCHED_LEFT or LineItemMatchStatus.UNMATCHED_RIGHT or LineItemMatchStatus.NOT_COMPARABLE);
    result.MatchCount=result.FieldResults.Count(x=>x.FunctionalOutcome==ReconciliationFunctionalOutcome.COINCIDE);result.MismatchCount=result.FieldResults.Count(x=>x.FunctionalOutcome is ReconciliationFunctionalOutcome.NO_COINCIDE or ReconciliationFunctionalOutcome.FALTA_EN_FACTURA or ReconciliationFunctionalOutcome.FALTA_EN_COVE);result.InsufficientEvidenceCount=result.FieldResults.Count(x=>x.FunctionalOutcome==ReconciliationFunctionalOutcome.NO_VERIFICABLE);result.ManualReviewCount=(pair.PairingStatus==InvoiceCovePairingStatus.MANUAL_REVIEW?1:0)+result.LineItemMatches.Count(x=>x.Status is LineItemMatchStatus.AMBIGUOUS or LineItemMatchStatus.NOT_COMPARABLE);result.NotApplicableCount=result.FieldResults.Count(x=>x.FunctionalOutcome==ReconciliationFunctionalOutcome.NO_APLICA);result.ComparableFieldCount=result.FieldResults.Count(x=>x.Treatment is ReconciliationFieldTreatment.DIRECT_COMPARE or ReconciliationFieldTreatment.TRANSFORM_AND_COMPARE);
    var required=profile.Fields.Where(x=>x.RequiredForCoverage).Select(x=>x.Id).ToHashSet();var applicable=result.FieldResults.Where(x=>required.Contains(x.ProfileFieldId)&&(x.Treatment is ReconciliationFieldTreatment.DIRECT_COMPARE or ReconciliationFieldTreatment.TRANSFORM_AND_COMPARE)).ToList();var evaluated=applicable.Count(x=>x.FunctionalOutcome is not ReconciliationFunctionalOutcome.NO_VERIFICABLE and not ReconciliationFunctionalOutcome.ERROR_DE_LECTURA);result.CoveragePercent=applicable.Count==0?null:decimal.Round(evaluated*100m/applicable.Count,4);
    result.CalculationJson=Calculations(pair.Left,pair.Right);
    var lineReview=result.LineItemMatches.Any(x=>x.Status is LineItemMatchStatus.AMBIGUOUS or LineItemMatchStatus.NOT_COMPARABLE);result.Outcome=pair.PairingStatus==InvoiceCovePairingStatus.MANUAL_REVIEW||lineReview?ReconciliationOutcome.MANUAL_REVIEW:result.MismatchCount>0||result.LineItemMatches.Any(x=>x.Status is LineItemMatchStatus.UNMATCHED_LEFT or LineItemMatchStatus.UNMATCHED_RIGHT)?ReconciliationOutcome.WITH_DIFFERENCES:result.InsufficientEvidenceCount>0||result.FieldResults.Any(x=>x.FunctionalOutcome==ReconciliationFunctionalOutcome.ERROR_DE_LECTURA)?ReconciliationOutcome.INSUFFICIENT_EVIDENCE:result.ComparableFieldCount==0?ReconciliationOutcome.NOT_APPLICABLE:ReconciliationOutcome.MATCH;
    result.Explanation=result.Outcome switch{ReconciliationOutcome.MATCH=>"La pareja confirmada coincide en todos los datos comparables evaluados.",ReconciliationOutcome.WITH_DIFFERENCES=>"La pareja confirmada contiene diferencias documentales técnicas; no constituye una conclusión LEGAL.",ReconciliationOutcome.MANUAL_REVIEW=>$"Evaluación provisional: {pair.Explanation}",ReconciliationOutcome.INSUFFICIENT_EVIDENCE=>"La evidencia disponible no permite verificar todos los datos aplicables.",_=>"No existen datos comparables aplicables."};
    result.SnapshotJson=JsonSerializer.Serialize(new{profile=new{profile.Code,profile.Version},pairing=new{result.PairingStatus,result.PairingMethod,result.PairingReasonCode,result.PairingExplanation},invoice=pair.Left is null?null:new{pair.Left.Id,pair.Left.OriginalFileName},cove=pair.Right is null?null:new{pair.Right.Id,pair.Right.OriginalFileName},result.Outcome,result.CoveragePercent,fields=result.FieldResults.Select(SnapshotField),lineItems=result.LineItemMatches.Select(x=>new{x.Status,x.MatchMethod,x.MatchKey,x.LeftItemSnapshot,x.RightItemSnapshot,x.Explanation}),calculations=JsonSerializer.Deserialize<JsonElement>(result.CalculationJson),result.EvaluatedAt});return result;
  }

  private static object SnapshotField(DocumentReconciliationFieldResult x)=>new{x.Section,x.DisplayName,x.LeftFieldCode,x.RightFieldCode,x.Treatment,x.FunctionalOutcome,x.ReasonCode,x.DeferredValidationTarget,x.LeftRawValue,x.RightRawValue,x.LeftNormalizedValue,x.RightNormalizedValue,x.LeftLocation,x.RightLocation,x.LeftExtractionMethod,x.RightExtractionMethod,x.NumericDifference,x.PercentDifference,x.Tolerance,x.EvidenceSource,x.Explanation};

  private static void AddUnmatchedLineResult(DocumentReconciliationResult result,DocumentReconciliationProfile profile,DocumentLineItemMatch match,List<DocumentLineItem> leftItems,List<DocumentLineItem> rightItems,OperationDocument leftDoc,OperationDocument rightDoc){
    var left=match.LeftLineItemId.HasValue?leftItems.Single(x=>x.Id==match.LeftLineItemId):null;var right=match.RightLineItemId.HasValue?rightItems.Single(x=>x.Id==match.RightLineItemId):null;var code=left?.PartNumber is not null||right?.PartNumber is not null?DocumentFieldCodes.PartNumber:left?.Sku is not null||right?.Sku is not null?DocumentFieldCodes.Sku:DocumentFieldCodes.DocumentNumber;var field=profile.Fields.FirstOrDefault(x=>x.LineItemScope==LineItemScope.LINE_ITEM&&(x.LeftFieldCode==code||x.RightFieldCode==code))??profile.Fields.First(x=>x.LineItemScope==LineItemScope.LINE_ITEM);var row=CompareV2(field,left is null?new(null,null,null,null):LineValueV2(left,field.LeftFieldCode),right is null?new(null,null,null,null):LineValueV2(right,field.RightFieldCode),leftDoc,rightDoc,left?.Id,right?.Id);
    if(match.Status is LineItemMatchStatus.AMBIGUOUS or LineItemMatchStatus.NOT_COMPARABLE){Set(row,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,match.Status==LineItemMatchStatus.AMBIGUOUS?"AMBIGUOUS_PAIRING":"INSUFFICIENT_EVIDENCE",match.Explanation);}result.FieldResults.Add(row);
  }

  private static void ApplyJointLineSemantics(List<DocumentReconciliationFieldResult> rows){
    var unit=rows.FirstOrDefault(x=>x.LeftFieldCode==DocumentFieldCodes.Unit);var quantity=rows.FirstOrDefault(x=>x.LeftFieldCode==DocumentFieldCodes.Quantity);var price=rows.FirstOrDefault(x=>x.LeftFieldCode==DocumentFieldCodes.UnitPrice);var total=rows.FirstOrDefault(x=>x.LeftFieldCode==DocumentFieldCodes.LineTotal);var currency=rows.FirstOrDefault(x=>x.LeftFieldCode==DocumentFieldCodes.Currency);
    if(unit is not null&&!string.IsNullOrWhiteSpace(unit.LeftNormalizedValue)&&!string.IsNullOrWhiteSpace(unit.RightNormalizedValue)&&!string.Equals(unit.LeftNormalizedValue,unit.RightNormalizedValue,StringComparison.OrdinalIgnoreCase)){var conversion=RequiresVerifiedFactor(unit.LeftNormalizedValue,unit.RightNormalizedValue);if(conversion){Set(unit,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,"CONVERSION_FACTOR_MISSING","Las unidades requieren un factor de conversión verificable que no está disponible.");if(quantity is not null)Set(quantity,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,"CONVERSION_FACTOR_MISSING","La cantidad no puede compararse sin convertir conjuntamente su unidad.");}else{Set(unit,ReconciliationFunctionalOutcome.NO_COINCIDE,CrossValidationOutcome.MISMATCH,"VALUE_MISMATCH","Las unidades comerciales normalizadas son incompatibles.");if(quantity is not null)Set(quantity,ReconciliationFunctionalOutcome.NO_COINCIDE,CrossValidationOutcome.MISMATCH,"UNIT_MISMATCH","La cantidad no coincide funcionalmente porque su unidad comercial es incompatible.");}if(price is not null)Set(price,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,"UNIT_BASIS_MISMATCH","El precio unitario no puede compararse con bases de unidad distintas.");}
    if(currency is not null&&!string.IsNullOrWhiteSpace(currency.LeftNormalizedValue)&&!string.IsNullOrWhiteSpace(currency.RightNormalizedValue)&&!string.Equals(currency.LeftNormalizedValue,currency.RightNormalizedValue,StringComparison.OrdinalIgnoreCase)){Set(currency,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,"CONVERSION_FACTOR_MISSING","Las monedas difieren y no existe conversión verificable aplicable.");if(price is not null)Set(price,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,"CONVERSION_FACTOR_MISSING","El precio unitario no puede compararse entre monedas sin tipo de cambio verificable.");if(total is not null)Set(total,ReconciliationFunctionalOutcome.NO_VERIFICABLE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE,"CONVERSION_FACTOR_MISSING","El importe de línea no puede compararse entre monedas sin tipo de cambio verificable.");}
  }
  private static bool RequiresVerifiedFactor(string left,string right){var packaging=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"BOX","CAJA","CARTON","CTN","PALLET","PLT","SET"};return packaging.Contains(left)||packaging.Contains(right);}
  private static void Set(DocumentReconciliationFieldResult row,ReconciliationFunctionalOutcome functional,CrossValidationOutcome outcome,string reason,string explanation){row.FunctionalOutcome=functional;row.Outcome=outcome;row.ReasonCode=reason;row.Explanation=explanation;}

  private static DocumentReconciliationFieldResult CompareV2(DocumentReconciliationProfileField field,ValueSnapshot left,ValueSnapshot right,OperationDocument? leftDoc,OperationDocument? rightDoc,Guid? leftItem,Guid? rightItem){
    var row=new DocumentReconciliationFieldResult{ProfileFieldId=field.Id,LeftLineItemId=leftItem,RightLineItemId=rightItem,Section=field.Section,DisplayName=string.IsNullOrWhiteSpace(field.DisplayName)?field.LeftFieldCode:field.DisplayName,LeftFieldCode=field.LeftFieldCode,RightFieldCode=field.RightFieldCode,Treatment=field.Treatment,DeferredValidationTarget=field.DeferredValidationTarget,LeftRawValue=left.Raw,RightRawValue=right.Raw,LeftNormalizedValue=left.Normalized,RightNormalizedValue=right.Normalized,LeftLocation=left.Location,RightLocation=right.Location,LeftExtractionMethod=left.Method,RightExtractionMethod=right.Method,Tolerance=Tolerance(field),EvidenceSource=Evidence(left.Method,right.Method)};
    if(field.Treatment is ReconciliationFieldTreatment.DEFER_TO_OTHER_DOCUMENT or ReconciliationFieldTreatment.REGISTER_ONLY or ReconciliationFieldTreatment.NOT_APPLICABLE){row.FunctionalOutcome=ReconciliationFunctionalOutcome.NO_APLICA;row.Outcome=CrossValidationOutcome.NOT_APPLICABLE;row.ReasonCode=field.Treatment.ToString();row.Explanation=field.Treatment==ReconciliationFieldTreatment.DEFER_TO_OTHER_DOCUMENT?$"Dato conservado y diferido a {field.DeferredValidationTarget??"otro documento"}; no se interpreta como faltante.":"Dato informativo conservado sin comparación directa.";return row;}
    if(Unreadable(leftDoc)||Unreadable(rightDoc)){row.FunctionalOutcome=ReconciliationFunctionalOutcome.ERROR_DE_LECTURA;row.Outcome=CrossValidationOutcome.INSUFFICIENT_EVIDENCE;row.ReasonCode="DOCUMENT_UNREADABLE";row.Explanation="La lectura documental no concluyó correctamente.";return row;}
    var leftMissing=string.IsNullOrWhiteSpace(left.Normalized);var rightMissing=string.IsNullOrWhiteSpace(right.Normalized);
    if(leftMissing||rightMissing){
      if(leftMissing&&!rightMissing&&field.ExpectedInLeft){row.FunctionalOutcome=ReconciliationFunctionalOutcome.FALTA_EN_FACTURA;row.Outcome=CrossValidationOutcome.MISMATCH;row.ReasonCode="MISSING_REQUIRED_INVOICE_FIELD";row.Explanation="El dato es exigible para la factura y sólo existe en el COVE.";return row;}
      if(rightMissing&&!leftMissing&&field.ExpectedInRight){row.FunctionalOutcome=ReconciliationFunctionalOutcome.FALTA_EN_COVE;row.Outcome=CrossValidationOutcome.MISMATCH;row.ReasonCode="MISSING_REQUIRED_COVE_FIELD";row.Explanation="El dato es exigible para el COVE y sólo existe en la factura.";return row;}
      row.FunctionalOutcome=ReconciliationFunctionalOutcome.NO_VERIFICABLE;row.Outcome=CrossValidationOutcome.INSUFFICIENT_EVIDENCE;row.ReasonCode="INSUFFICIENT_EVIDENCE";row.Explanation="La evidencia estructurada no permite verificar el dato.";return row;
    }
    var compared=Compare(field,left,right,leftItem,rightItem);row.NumericDifference=compared.NumericDifference;row.PercentDifference=compared.PercentDifference;row.Outcome=compared.Outcome;row.Explanation=compared.Explanation;
    if(compared.Outcome==CrossValidationOutcome.MATCH){row.FunctionalOutcome=ReconciliationFunctionalOutcome.COINCIDE;row.ReasonCode="MATCH";}
    else if(compared.Outcome==CrossValidationOutcome.MISMATCH){row.FunctionalOutcome=ReconciliationFunctionalOutcome.NO_COINCIDE;row.ReasonCode="VALUE_MISMATCH";}
    else{row.FunctionalOutcome=ReconciliationFunctionalOutcome.NO_VERIFICABLE;row.ReasonCode=compared.Outcome==CrossValidationOutcome.MANUAL_REVIEW?"SEMANTIC_EQUIVALENCE_UNPROVEN":"INSUFFICIENT_EVIDENCE";}
    return row;
  }

  private static bool Unreadable(OperationDocument? document)=>document?.IntelligenceStatus is DocumentIntelligenceStatus.DOCUMENT_UNREADABLE or DocumentIntelligenceStatus.OCR_UNAVAILABLE or DocumentIntelligenceStatus.ERROR_DE_LECTURA;
  private static ValueSnapshot HeaderValue(OperationDocument? doc,string code){
    if(doc is null)return new(null,null,null,null);
    if(code.StartsWith("PARTICIPANT|",StringComparison.Ordinal)){var parts=code.Split('|');if(parts.Length==3){var roles=parts[1].Split(',').Select(x=>Enum.TryParse<DocumentParticipantRole>(x,true,out var role)?role:(DocumentParticipantRole?)null).Where(x=>x.HasValue).Select(x=>x!.Value).ToHashSet();var participant=doc.Participants.Where(x=>roles.Contains(x.Role)).OrderByDescending(x=>x.AnalysisVersion).ThenByDescending(x=>x.ConfidenceLevel).FirstOrDefault();var value=participant is null?null:parts[2] switch{"NAME"=>participant.Name,"TAX_ID"=>participant.TaxId,"ADDRESS"=>participant.RawAddress,"STREET"=>participant.Street,"NUMBER"=>participant.ExteriorNumber,"POSTAL_CODE"=>participant.PostalCode,"CITY"=>participant.City,"STATE"=>participant.State,"COUNTRY"=>participant.Country,_=>null};return new(participant?.Id,value,Normalize(value),participant is null?null:ExtractionMethod.PDF_TEXT,participant?.SourceLocator);}}
    return Field(doc,code);
  }
  private static string? Normalize(string? value)=>string.IsNullOrWhiteSpace(value)?null:Regex.Replace(value.Trim().ToUpperInvariant(),@"[\p{P}\s]+"," ").Trim();
  private static ValueSnapshot LineValueV2(DocumentLineItem item,string code){object? value=code switch{DocumentFieldCodes.DocumentNumber=>item.ItemNumber,DocumentFieldCodes.PartNumber=>item.PartNumber,DocumentFieldCodes.Sku=>item.Sku,DocumentFieldCodes.Description=>item.Description,DocumentFieldCodes.Brand=>item.Brand,DocumentFieldCodes.Model=>item.Model,DocumentFieldCodes.Submodel=>item.Submodel,DocumentFieldCodes.SerialNumber=>item.SerialNumber,DocumentFieldCodes.Quantity=>item.Quantity,DocumentFieldCodes.Unit=>item.Unit,DocumentFieldCodes.UnitPrice=>item.UnitValue,DocumentFieldCodes.LineTotal or DocumentFieldCodes.TotalAmount or DocumentFieldCodes.CommercialValue=>item.TotalValue,DocumentFieldCodes.Currency=>item.Currency,DocumentFieldCodes.CountryOfOrigin=>item.CountryOfOrigin,_=>null};var raw=value is IFormattable f?f.ToString(null,CultureInfo.InvariantCulture):value?.ToString();var normalized=code==DocumentFieldCodes.Unit?NormalizeUnit(raw):code is DocumentFieldCodes.Quantity or DocumentFieldCodes.UnitPrice or DocumentFieldCodes.LineTotal or DocumentFieldCodes.TotalAmount or DocumentFieldCodes.CommercialValue or DocumentFieldCodes.UsdEquivalent?raw?.Trim():raw is null?null:Normalize(raw);return new(null,raw,normalized,item.ExtractionMethod,item.RawLocator??(item.PageNumber.HasValue?$"Página {item.PageNumber}":null));}
  private static string? NormalizeUnit(string? value)=>value?.Trim().ToUpperInvariant() switch{"PIEZA" or "PIEZAS" or "PZ" or "PZS" or "PCS"=>"PZA","KGS"=>"KG","LBS"=>"LB",var v=>v};
  private static string Calculations(OperationDocument? invoice,OperationDocument? cove){
    var rows=new List<object>();Add(invoice,"FACTURA");Add(cove,"COVE");return JsonSerializer.Serialize(rows);
    void Add(OperationDocument? document,string side){if(document is null)return;foreach(var item in document.LineItems.OrderBy(x=>x.Sequence)){decimal? calculated=item.Quantity.HasValue&&item.UnitValue.HasValue?decimal.Round(item.Quantity.GetValueOrDefault()*item.UnitValue.GetValueOrDefault(),6):null;decimal? lineDifference=calculated.HasValue&&item.TotalValue.HasValue?Math.Abs(calculated.GetValueOrDefault()-item.TotalValue.GetValueOrDefault()):null;rows.Add(new{side,scope="LINE_ITEM",itemId=item.Id,item.Sequence,formula="QUANTITY * UNIT_PRICE = LINE_TOTAL",inputs=new{item.Quantity,item.UnitValue},calculated,declared=item.TotalValue,difference=lineDifference,rounding="6_DECIMALS",outcome=calculated.HasValue&&item.TotalValue.HasValue?(calculated.GetValueOrDefault()==item.TotalValue.GetValueOrDefault()?"COINCIDE":"NO_COINCIDE"):"NO_VERIFICABLE",item.RawLocator});}var sum=document.LineItems.Where(x=>x.TotalValue.HasValue).Sum(x=>x.TotalValue??0);var total=Field(document,DocumentFieldCodes.TotalAmount);if(string.IsNullOrWhiteSpace(total.Normalized))total=Field(document,DocumentFieldCodes.CommercialTotal);decimal? declared=decimal.TryParse(total.Normalized,NumberStyles.Number,CultureInfo.InvariantCulture,out var parsed)?parsed:null;decimal? totalDifference=declared.HasValue?Math.Abs(sum-declared.GetValueOrDefault()):null;rows.Add(new{side,scope="DOCUMENT",formula="SUM(LINE_TOTAL) = COMMERCIAL_TOTAL",inputs=new{lineTotalSum=sum,lineCount=document.LineItems.Count},calculated=sum,declared,difference=totalDifference,rounding="6_DECIMALS",outcome=declared.HasValue?(sum==declared.GetValueOrDefault()?"COINCIDE":"NO_COINCIDE"):"NO_VERIFICABLE",location=total.Location});}
  }

  private DocumentReconciliationResult Build(TradeOperation operation,DocumentReconciliationProfile profile,Pair pair,List<CrossValidationResult> crosses){
    var result=new DocumentReconciliationResult{TradeOperationId=operation.Id,ProfileId=profile.Id,ProfileCode=profile.Code,ProfileVersion=profile.Version,LeftDocumentId=pair.Left?.Id,RightDocumentId=pair.Right?.Id,EvaluatedAt=DateTime.UtcNow};
    foreach(var field in profile.Fields.Where(x=>x.LineItemScope==LineItemScope.HEADER).OrderBy(x=>x.Sequence))result.FieldResults.Add(Header(field,pair,crosses));
    var leftItems=pair.Left?.LineItems.OrderBy(x=>x.Sequence).ToList()??[];var rightItems=pair.Right?.LineItems.OrderBy(x=>x.Sequence).ToList()??[];result.LineItemsLeft=leftItems.Count;result.LineItemsRight=rightItems.Count;
    if(!pair.Ambiguous&&pair.Left is not null&&pair.Right is not null){foreach(var match in matcher.Match(leftItems,rightItems)){result.LineItemMatches.Add(match);if(match.Status==LineItemMatchStatus.MATCHED){var l=leftItems.Single(x=>x.Id==match.LeftLineItemId);var r=rightItems.Single(x=>x.Id==match.RightLineItemId);foreach(var field in profile.Fields.Where(x=>x.LineItemScope==LineItemScope.LINE_ITEM).OrderBy(x=>x.Sequence))result.FieldResults.Add(Line(field,l,r));}}}
    result.LineItemsMatched=result.LineItemMatches.Count(x=>x.Status==LineItemMatchStatus.MATCHED);result.LineItemsUnmatched=result.LineItemMatches.Count(x=>x.Status is LineItemMatchStatus.UNMATCHED_LEFT or LineItemMatchStatus.UNMATCHED_RIGHT);
    result.ComparableFieldCount=result.FieldResults.Count;result.MatchCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.MATCH);result.MismatchCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.MISMATCH);result.InsufficientEvidenceCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.INSUFFICIENT_EVIDENCE);result.ManualReviewCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.MANUAL_REVIEW);result.NotApplicableCount=result.FieldResults.Count(x=>x.Outcome==CrossValidationOutcome.NOT_APPLICABLE);
    var requiredFields=profile.Fields.Where(x=>x.RequiredForCoverage).Select(x=>x.Id).ToHashSet();var expected=result.FieldResults.Count(x=>requiredFields.Contains(x.ProfileFieldId));var evaluated=result.FieldResults.Count(x=>requiredFields.Contains(x.ProfileFieldId)&&x.Outcome is CrossValidationOutcome.MATCH or CrossValidationOutcome.MISMATCH);result.CoveragePercent=expected==0?null:decimal.Round(evaluated*100m/expected,4);
    var ambiguous=pair.Ambiguous||result.LineItemMatches.Any(x=>x.Status==LineItemMatchStatus.AMBIGUOUS);var unmatched=result.LineItemMatches.Any(x=>x.Status is LineItemMatchStatus.UNMATCHED_LEFT or LineItemMatchStatus.UNMATCHED_RIGHT);result.Outcome=result.MismatchCount>0||unmatched?ReconciliationOutcome.WITH_DIFFERENCES:ambiguous||result.ManualReviewCount>0?ReconciliationOutcome.MANUAL_REVIEW:result.InsufficientEvidenceCount>0?ReconciliationOutcome.INSUFFICIENT_EVIDENCE:result.ComparableFieldCount==0?ReconciliationOutcome.NOT_APPLICABLE:ReconciliationOutcome.MATCH;
    result.Explanation=pair.Ambiguous?pair.Explanation:result.Outcome switch{ReconciliationOutcome.MATCH=>"Todos los campos estructurados comparables y partidas vinculadas coinciden.",ReconciliationOutcome.WITH_DIFFERENCES=>"Se detectaron diferencias técnicas o partidas sin correspondencia; no equivale a incumplimiento legal.",ReconciliationOutcome.INSUFFICIENT_EVIDENCE=>"No existe evidencia estructurada suficiente para completar la reconciliación.",ReconciliationOutcome.MANUAL_REVIEW=>"La vinculación documental o de partidas es ambigua y requiere revisión humana.",_=>"No existen campos aplicables para reconciliar."};
    result.SnapshotJson=JsonSerializer.Serialize(new{profile=new{profile.Code,profile.Version},leftDocument=pair.Left is null?null:new{pair.Left.Id,pair.Left.OriginalFileName},rightDocument=pair.Right is null?null:new{pair.Right.Id,pair.Right.OriginalFileName},result.Outcome,result.CoveragePercent,fields=result.FieldResults.Select(x=>new{x.Section,x.LeftFieldCode,x.RightFieldCode,x.LeftRawValue,x.RightRawValue,x.LeftNormalizedValue,x.RightNormalizedValue,x.LeftExtractionMethod,x.RightExtractionMethod,x.Outcome,x.NumericDifference,x.PercentDifference,x.Tolerance,x.RuleCode,x.EvidenceSource,x.Explanation}),lineItems=result.LineItemMatches.Select(x=>new{x.Status,x.MatchMethod,x.MatchKey,x.LeftItemSnapshot,x.RightItemSnapshot,x.Explanation}),evaluatedAt=result.EvaluatedAt});return result;
  }

  private static DocumentReconciliationFieldResult Header(DocumentReconciliationProfileField field,Pair pair,List<CrossValidationResult> crosses){
    var reused=field.CrossValidationRuleId.HasValue?crosses.FirstOrDefault(x=>x.CrossValidationRuleId==field.CrossValidationRuleId&&x.SourceDocumentId==pair.Left?.Id&&x.TargetDocumentId==pair.Right?.Id):null;if(reused is not null)return new(){ProfileFieldId=field.Id,CrossValidationResultId=reused.Id,Section=field.Section,LeftFieldCode=field.LeftFieldCode,RightFieldCode=field.RightFieldCode,LeftRawValue=reused.SourceRawValue,RightRawValue=reused.TargetRawValue,LeftNormalizedValue=reused.SourceNormalizedValue,RightNormalizedValue=reused.TargetNormalizedValue,LeftExtractionMethod=reused.SourceField?.ExtractionMethod,RightExtractionMethod=reused.TargetField?.ExtractionMethod??(reused.TargetFieldId is null&&reused.TargetRawValue is not null?ExtractionMethod.EXISTING_METADATA:null),Outcome=reused.Outcome,NumericDifference=reused.NumericDifference,PercentDifference=reused.PercentDifference,Tolerance=Tolerance(field),RuleCode=reused.RuleCode,EvidenceSource=Evidence(reused.SourceField?.ExtractionMethod,reused.TargetField?.ExtractionMethod),Explanation=$"Resultado CROSS {reused.RuleCode} reutilizado. {reused.Explanation}"};
    var left=Field(pair.Left,field.LeftFieldCode);var right=Field(pair.Right,field.RightFieldCode);return Compare(field,left,right,null,null);
  }
  private static DocumentReconciliationFieldResult Line(DocumentReconciliationProfileField field,DocumentLineItem left,DocumentLineItem right){var l=LineValue(left,field.LeftFieldCode);var r=LineValue(right,field.RightFieldCode);return Compare(field,l,r,left.Id,right.Id);}
  private static DocumentReconciliationFieldResult Compare(DocumentReconciliationProfileField field,ValueSnapshot left,ValueSnapshot right,Guid? leftItem,Guid? rightItem){
    var row=new DocumentReconciliationFieldResult{ProfileFieldId=field.Id,LeftLineItemId=leftItem,RightLineItemId=rightItem,Section=field.Section,LeftFieldCode=field.LeftFieldCode,RightFieldCode=field.RightFieldCode,LeftRawValue=left.Raw,RightRawValue=right.Raw,LeftNormalizedValue=left.Normalized,RightNormalizedValue=right.Normalized,LeftExtractionMethod=left.Method,RightExtractionMethod=right.Method,Tolerance=Tolerance(field),RuleCode=field.CrossValidationRule?.Code,EvidenceSource=Evidence(left.Method,right.Method)};
    if(string.IsNullOrWhiteSpace(left.Normalized)||string.IsNullOrWhiteSpace(right.Normalized)){row.Outcome=CrossValidationOutcome.INSUFFICIENT_EVIDENCE;row.Explanation="Falta evidencia estructurada en al menos uno de los documentos; la ausencia no se considera diferencia.";return row;}
    if(field.ComparisonType is CrossComparisonType.EXACT_NUMERIC or CrossComparisonType.NUMERIC_TOLERANCE or CrossComparisonType.PERCENT_TOLERANCE or CrossComparisonType.CURRENCY_AMOUNT){if(!decimal.TryParse(left.Normalized,NumberStyles.Number,CultureInfo.InvariantCulture,out var lv)||!decimal.TryParse(right.Normalized,NumberStyles.Number,CultureInfo.InvariantCulture,out var rv)){row.Outcome=CrossValidationOutcome.MANUAL_REVIEW;row.Explanation="Los valores no pudieron interpretarse inequívocamente como números.";return row;}row.NumericDifference=Math.Abs(lv-rv);row.PercentDifference=rv==0?(lv==0?0:null):Math.Abs((lv-rv)/rv*100m);var ok=field.ComparisonType switch{CrossComparisonType.EXACT_NUMERIC or CrossComparisonType.CURRENCY_AMOUNT=>row.NumericDifference==0,CrossComparisonType.NUMERIC_TOLERANCE=>row.NumericDifference<=(field.ToleranceValue??0),CrossComparisonType.PERCENT_TOLERANCE=>row.PercentDifference.HasValue&&row.PercentDifference<=(field.ToleranceValue??0),_=>false};row.Outcome=ok?CrossValidationOutcome.MATCH:CrossValidationOutcome.MISMATCH;row.Explanation=ok?"Los valores numéricos coinciden dentro de la tolerancia.":$"Diferencia documental: {row.NumericDifference.Value.ToString(CultureInfo.InvariantCulture)}.";return row;}
    var match=field.ComparisonType==CrossComparisonType.EXACT_TEXT?string.Equals(left.Raw,right.Raw,StringComparison.Ordinal):string.Equals(left.Normalized,right.Normalized,StringComparison.OrdinalIgnoreCase);row.Outcome=match?CrossValidationOutcome.MATCH:CrossValidationOutcome.MISMATCH;row.Explanation=match?"Los valores normalizados coinciden.":"Los valores normalizados son distintos; este resultado es técnico, no legal.";return row;
  }

  private static List<OperationDocument> OfType(List<OperationDocument> docs,string code){var aliases=Aliases.GetValueOrDefault(code)??[code];return docs.Where(x=>aliases.Contains(x.DocumentType.Code,StringComparer.OrdinalIgnoreCase)).OrderBy(x=>x.UploadedAt).ThenBy(x=>x.Id).ToList();}
  private static List<Pair> PairDocuments(List<OperationDocument> left,List<OperationDocument> right){if(left.Count==0)return right.Select(x=>new Pair(null,x,false,"Documento izquierdo no disponible.")).ToList();if(right.Count==0)return left.Select(x=>new Pair(x,null,false,"Documento derecho no disponible.")).ToList();if(left.Count==1&&right.Count==1)return[new(left[0],right[0],false,"Pareja documental única.")];var result=new List<Pair>();var used=new HashSet<Guid>();foreach(var l in left){var keys=Keys(l);var candidates=right.Where(r=>!used.Contains(r.Id)&&keys.Overlaps(Keys(r))).ToList();if(candidates.Count==1){used.Add(candidates[0].Id);result.Add(new(l,candidates[0],false,"Pareja resuelta por referencia documental exacta."));}else if(candidates.Count>1)result.Add(new(l,null,true,"Existen múltiples documentos candidatos con la misma referencia."));else result.Add(new(l,null,true,"No fue posible determinar una pareja documental inequívoca."));}foreach(var r in right.Where(x=>!used.Contains(x.Id)&&result.All(p=>p.Right?.Id!=x.Id)))result.Add(new(null,r,true,"Documento derecho sin pareja inequívoca."));return result;}
  private static HashSet<string> Keys(OperationDocument doc){var values=doc.References.Select(x=>x.Value).Concat(doc.Fields.Where(x=>x.FieldCode is DocumentFieldCodes.InvoiceNumber or DocumentFieldCodes.CoveNumber or DocumentFieldCodes.DocumentNumber).Select(x=>x.NormalizedValue??x.RawValue)).Append(doc.DocumentNumber);return values.Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>Regex.Replace(x!.Trim().ToUpperInvariant(),@"[^A-Z0-9]","")).Where(x=>x.Length>0).ToHashSet(StringComparer.OrdinalIgnoreCase);}
  private static ValueSnapshot Field(OperationDocument? doc,string code){var field=doc?.Fields.Where(x=>x.FieldCode==code).OrderByDescending(x=>Priority(x.ExtractionMethod)).ThenByDescending(x=>x.IsManuallyConfirmed).ThenByDescending(x=>x.Confidence).FirstOrDefault();return new(field?.Id,field?.RawValue,field?.NormalizedValue,field?.ExtractionMethod,field?.SourceLocator);}
  private static int Priority(ExtractionMethod method)=>method switch{ExtractionMethod.MANUAL=>5,ExtractionMethod.XML=>4,ExtractionMethod.PDF_TEXT=>3,ExtractionMethod.FILENAME=>2,ExtractionMethod.EXISTING_METADATA=>1,_=>0};
  private static ValueSnapshot LineValue(DocumentLineItem item,string code){object? value=code switch{DocumentFieldCodes.DocumentNumber=>item.ItemNumber,DocumentFieldCodes.Description=>item.Description,DocumentFieldCodes.Quantity=>item.Quantity,DocumentFieldCodes.Unit=>item.Unit,DocumentFieldCodes.UnitPrice=>item.UnitValue,DocumentFieldCodes.TotalAmount or DocumentFieldCodes.CommercialValue=>item.TotalValue,DocumentFieldCodes.Currency=>item.Currency,DocumentFieldCodes.TariffFraction=>item.TariffFraction,DocumentFieldCodes.Nico=>item.Nico,DocumentFieldCodes.GrossWeight=>item.GrossWeight,DocumentFieldCodes.NetWeight=>item.NetWeight,DocumentFieldCodes.OriginCountry=>item.CountryOfOrigin,"PART_NUMBER"=>item.PartNumber??item.Sku,_=>null};var raw=value is IFormattable f?f.ToString(null,CultureInfo.InvariantCulture):value?.ToString();var normalized=code==DocumentFieldCodes.Description?Regex.Replace(raw?.Trim().ToUpperInvariant()??"",@"[\p{P}\s]+"," ").Trim():code==DocumentFieldCodes.Unit?raw?.Trim().ToUpperInvariant() switch{"PIEZA" or "PIEZAS" or "PZ" or "PZS" or "PCS"=>"PZA","KGS"=>"KG","LBS"=>"LB",var v=>v}:raw?.Trim().ToUpperInvariant();return new(null,raw,string.IsNullOrWhiteSpace(normalized)?null:normalized,item.ExtractionMethod);}
  private static string Evidence(ExtractionMethod? left,ExtractionMethod? right)=>$"LEFT:{left?.ToString()??"MISSING"}; RIGHT:{right?.ToString()??"MISSING"}";
  private static string Tolerance(DocumentReconciliationProfileField field)=>field.ToleranceType is null?"EXACT":$"{field.ToleranceType}:{field.ToleranceValue?.ToString(CultureInfo.InvariantCulture)??"0"}";
  private async Task<Guid?> ValidUser(Guid id,CancellationToken ct)=>id!=Guid.Empty&&await db.Users.AnyAsync(x=>x.Id==id,ct)?id:null;
}
